"%USERPROFILE%\\AppData\\Local\\Microsoft\\WindowsApps\\Microsoft.PowerShell_8wekyb3d8bbwe\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
foreach ("'$cgsPath in @('"'.scratch/cli-full-20261118/story.md', 'production/session-state/active.md')) {
  "'$cgsHash = [System.Security.Cryptography.SHA256]::Create()
  try { $cgsFileBytes = [System.IO.File]::ReadAllBytes((Get-Item -LiteralPath $cgsPath).FullName); $cgsHex = [System.BitConverter]::ToString($cgsHash.ComputeHash($cgsFileBytes)).Replace('"'-', '').ToLowerInvariant(); Write-Output \""'$cgsPath $($cgsFileBytes.Length) $cgsHex" } finally { $cgsHash.Dispose() }
}
Get-Item -LiteralPath '"'production', 'production/qa', 'production/session-state' | Select-Object FullName, Attributes"

"%USERPROFILE%\\AppData\\Local\\Microsoft\\WindowsApps\\Microsoft.PowerShell_8wekyb3d8bbwe\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$cgsCheckpointFile = (Get-Item -LiteralPath '"'production/session-state/active.md').FullName
"'$cgsStoryFile = (Get-Item -LiteralPath '"'.scratch/cli-full-20261118/story.md').FullName
"'$cgsEncoding = [System.Text.UTF8Encoding]::new($false, $true)
$cgsExpectedStoryHash = '"'a4838dd8480b24d0c678809a86ae42fef310217cc2c17fa4890c06160d993233'
"'$cgsExpectedCheckpointHash = '"'45ae7d0cd07390d0998e5c665a2ed71b50cb43c7cd98dc50f12003feb27c7b59'
function Get-CgsSha256([byte[]] "'$cgsBytes) {
  $cgsAlgorithm = [System.Security.Cryptography.SHA256]::Create()
  try { return [System.BitConverter]::ToString($cgsAlgorithm.ComputeHash($cgsBytes)).Replace('"'-', '').ToLowerInvariant() } finally { "'$cgsAlgorithm.Dispose() }
}
$cgsStoryBefore = [System.IO.File]::ReadAllBytes($cgsStoryFile)
if ((Get-CgsSha256 $cgsStoryBefore) -cne $cgsExpectedStoryHash) { throw '"'Story byte hash changed since preflight' }
"'$cgsEntry = '"'<"'!-- QA-PLAN: 2026-11-18 | System: CLI Full Acceptance | Plan written: production/qa/qa-plan-cli-full-20261118-2026-11-18.md | Story back-fill: not written -->'"'
"'$cgsCheckpointBefore = [System.IO.File]::ReadAllBytes($cgsCheckpointFile)
if ((Get-CgsSha256 $cgsCheckpointBefore) -cne $cgsExpectedCheckpointHash) { throw '"'Checkpoint changed since preflight' }
"'$cgsCheckpointText = $cgsEncoding.GetString($cgsCheckpointBefore)
$cgsNewline = if ($cgsCheckpointText.Contains("`r`n")) { "`r`n" } else { "`n" }
$cgsAppend = if ($cgsCheckpointText.EndsWith("`n")) { $cgsEntry + $cgsNewline } else { $cgsNewline + $cgsEntry + $cgsNewline }
[System.IO.File]::AppendAllText($cgsCheckpointFile, $cgsAppend, $cgsEncoding)
$cgsExpectedCheckpoint = [byte[]] ($cgsCheckpointBefore + $cgsEncoding.GetBytes($cgsAppend))
$cgsCheckpointAfter = [System.IO.File]::ReadAllBytes($cgsCheckpointFile)
if ([System.Convert]::ToBase64String($cgsCheckpointAfter) -cne [System.Convert]::ToBase64String($cgsExpectedCheckpoint)) { throw '"'Checkpoint append verification failed' }
"'$cgsStoryAfter = [System.IO.File]::ReadAllBytes($cgsStoryFile)
$cgsStoryHash = Get-CgsSha256 $cgsStoryAfter
if ($cgsStoryHash -cne $cgsExpectedStoryHash) { throw '"'Story byte hash changed after writes' }
Write-Output ('Story byte hash unchanged: ' + "'$cgsStoryAfter.Length + '"' bytes SHA256 ' + "'$cgsStoryHash)
Write-Output ('"'Checkpoint preserved with one appended entry: ' + "'$cgsEntry)'
